import{_ as e}from"./chunks/1c4467b41961bde0fa1aee34061b93d9.B03u6GuX.js";import{_ as a,c as r,a2 as o,o as l}from"./chunks/framework.BnrAgU0Y.js";const u=JSON.parse('{"title":"基础提示","description":"基础提示","frontmatter":{"title":"基础提示","description":"基础提示","layout":"doc"},"headers":[],"relativePath":"langflow/starter-projects-basic-prompting.md","filePath":"langflow/starter-projects-basic-prompting.md"}'),n={name:"langflow/starter-projects-basic-prompting.md"};function s(i,t,p,g,c,d){return l(),r("div",null,t[0]||(t[0]=[o('<h1 id="基础提示" tabindex="-1">基础提示 <a class="header-anchor" href="#基础提示" aria-label="Permalink to &quot;基础提示&quot;">​</a></h1><p>提示（prompt）作为输入提供给大型语言模型（Large Language Model, LLM），它们在人工指令和计算任务之间起到接口作用。</p><p>通过在提示中以自然语言向 LLM 提交请求，你可以获取答案、生成文本以及解决问题。</p><p>本文将演示如何使用 Langflow 的提示工具向 LLM 发出基本提示，并展示不同提示策略如何影响你的结果。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li><a href="/bllm/get-started-installation.html">Langflow 已安装并运行</a></li><li><a href="https://platform.openai.com/" target="_blank" rel="noreferrer">已创建 OpenAI API 密钥</a></li></ul><h2 id="创建基础提示流程" tabindex="-1">创建基础提示流程 <a class="header-anchor" href="#创建基础提示流程" aria-label="Permalink to &quot;创建基础提示流程&quot;">​</a></h2><ol><li>在 Langflow 仪表盘中，点击 <strong>New Flow</strong>。</li><li>选择 <strong>Basic Prompting</strong>。</li><li>已创建 <strong>Basic Prompting</strong> 流程。</li></ol><p><img src="'+e+'" alt=""></p><p>这个流程让您可以与 <strong>OpenAI 模型</strong>组件进行聊天。模型将根据 <strong>Prompt</strong>（提示词）组件中构建的提示进行响应。</p><ol start="4"><li>要检查 <strong>Template</strong>（模板），在 <strong>Prompt</strong> 组件中，点击 <strong>Template</strong> 字段。</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Answer the user as if you were a GenAI expert, enthusiastic about helping them get started building something fresh.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="5"><li><p>要为 <strong>OpenAI</strong> 组件创建一个环境变量，在 <strong>OpenAI API Key</strong>（OpenAI API 密钥）字段中，点击 <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-globe" aria-label="Globe icon"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"></path><path d="M2 12h20"></path></svg> <strong>Globe</strong>（地球）按钮，再点击 <strong>Add New Variable</strong>（添加新变量）。</p><ol><li>在 <strong>Variable Name</strong>（变量名称）字段中，输入 <code>openai_api_key</code>。</li><li>在 <strong>Value</strong>（值）字段中，粘贴您的 OpenAI API 密钥 (<code>sk-...</code>)。</li><li>点击 <strong>Save Variable</strong>（保存变量）。</li></ol></li></ol><h2 id="运行基本提示流程" tabindex="-1">运行基本提示流程 <a class="header-anchor" href="#运行基本提示流程" aria-label="Permalink to &quot;运行基本提示流程&quot;">​</a></h2><ol><li>点击 <strong>Playground</strong> 按钮。</li><li>输入信息并按 Enter 键。机器人应以明显的海盗风格做出响应！</li></ol><h2 id="修改提示以获得不同结果" tabindex="-1">修改提示以获得不同结果 <a class="header-anchor" href="#修改提示以获得不同结果" aria-label="Permalink to &quot;修改提示以获得不同结果&quot;">​</a></h2><ol><li><p>要修改提示的结果，在 <strong>Prompt</strong> 组件中，点击 <strong>Template</strong> 字段。<strong>编辑提示</strong> 窗口随即打开。</p></li><li><p>将现有的提示更改为不同的角色，例如：<code>像赫敏·格兰杰（Hermione Granger）一样回答用户。</code></p></li><li><p>再次运行工作流程，并注意提示如何改变模型的响应。</p></li></ol>',17)]))}const b=a(n,[["render",s]]);export{u as __pageData,b as default};
